async function put(q){lifeCheck();if(full(bot.blockAt(q)))return;if(bodies.has(key(q)))throw Error('BUILD_SHARED_BODY '+q);const ref=[new Vec3(0,-1,0),...dirs,new Vec3(0,1,0)].map(d=>q.plus(d)).find(p=>full(bot.blockAt(p)));if(!ref)throw Error('NO_REFERENCE');await bot.equip(materials.map(n=>bot.inventory.items().find(i=>i.name===n)).find(Boolean),'hand');await bot._placeBlockWithOptions(bot.blockAt(ref),q.minus(ref),{forceLook:true});await bot.waitForTicks(4);if(!full(bot.blockAt(q)))throw Error('PUT_POST');}
async function cut(q,ownFloor=false){lifeCheck();const b=bot.blockAt(q);if(b.boundingBox==='empty')return;if(floors.has(key(q))&&!ownFloor)throw Error('SHARED_FLOOR_CUT '+q);if(!['basalt','blackstone','netherrack','cobblestone','dirt','spruce_planks'].includes(b.name))throw Error('CUT_KIND '+b.name);for(const d of[...dirs,new Vec3(0,-1,0),new Vec3(0,1,0)])if(/lava|fire|gravel|sand/.test(bot.blockAt(q.plus(d))?.name))throw Error('CUT_HAZARD');const pick=bot.inventory.items().filter(i=>i.name.endsWith('_pickaxe')).sort((a,b)=>a.durabilityUsed-b.durabilityUsed)[0];if(!pick)throw Error('NO_PICK');await bot.equip(pick,'hand');await bot.dig(b);await bot.waitForTicks(5);lifeCheck();}
async function go(q){lifeCheck();const m=new Movements(bot);m.canDig=false;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=2;m.getMoveDiagonal=()=>{};for(const n of['lava','fire','magma_block','nether_portal'])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);bot.pathfinder.setMovements(m);let timer,error=null;try{await Promise.race([bot.pathfinder.goto(new goals.GoalBlock(q.x,q.y,q.z)),new Promise((_,r)=>timer=setTimeout(()=>{bot.pathfinder.setGoal(null);r(Error('NAV_BOUND'));},4500))]);}catch(e){error=e;}finally{clearTimeout(timer);bot.clearControlStates();bot.pathfinder.setGoal(null);}await bot.waitForTicks(8);lifeCheck();if(!bot.entity.onGround||!bot.entity.position.floored().equals(q)||bot.entity.position.distanceTo(q.offset(.5,0,.5))>.7)throw error||Error('NOT_ARRIVED');if(error)console.log('ACTUAL_AFTER_BOUND',q.toString());}
function profile(q){const f=q.offset(0,-3,0);return !bodies.has(key(q.offset(0,-1,0)))&&full(bot.blockAt(f.offset(0,-1,0)))&&[1,2,3].every(y=>full(bot.blockAt(q.offset(0,-y,0))))&&dirs.every(d=>[0,1].every(y=>full(bot.blockAt(f.plus(d).offset(0,y,0)))));}
async function pillar(){lifeCheck();const p=bot.entity.position.floored(),base=bot.blockAt(p.offset(0,-1,0));if(!full(base))throw Error('PILLAR_BASE');await bot.equip(materials.map(n=>bot.inventory.items().find(i=>i.name===n)).find(Boolean),'hand');await bot.lookAt(base.position.offset(.5,1,.5),true);bot.setControlState('jump',true);try{let high=false;for(let k=0;k<16;k++){await bot.waitForTicks(1);lifeCheck();if(bot.entity.position.y>p.y+1.15){high=true;break}}if(!high)throw Error('NO_JUMP');await bot._placeBlockWithOptions(base,new Vec3(0,1,0),{forceLook:true});}finally{bot.clearControlStates();}await bot.waitForTicks(10);if(!bot.entity.onGround||!bot.entity.position.floored().equals(p.offset(0,1,0)))throw Error('PILLAR_POST');}
function cube(p){return [p.offset(0,-1,0),p.offset(0,2,0),...dirs.flatMap(d=>[p.plus(d),p.plus(d).offset(0,1,0)])].every(q=>full(bot.blockAt(q)));}
async function bury(q){lifeCheck();activeBurial=q;await go(new Vec3(q.x,bot.entity.position.floored().y,q.z));while(bot.entity.position.y>q.y-3+.05){const f=bot.entity.position.floored().offset(0,-1,0);await cut(f,true);await bot.waitForTicks(8);if(!bot.entity.onGround||Math.abs(bot.entity.position.y-f.y)>.05)throw Error('BURIAL_SETTLE');}await put(q.offset(0,-1,0));const p=q.offset(0,-3,0);if(!cube(p))throw Error('BURIAL_CUBE');global.p3TravelBurial={surface:[q.x,q.y,q.z],foot:[p.x,p.y,p.z]};}
let target=start;for(let i=start+1;i<Math.min(route.length,start+65);i++)if(profile(route[i]))target=i;
try{bot.pathfinder.setGoal(null);bot.clearControlStates();lifeCheck();if(!cube(new Vec3(...state.foot))||!bot.entity.position.floored().equals(new Vec3(...state.foot)))throw Error('START_CUBE');if(target===start)throw Error('NO_NEW_ENDPOINT');guard(origin);await cut(origin.offset(0,-1,0),true);for(let k=0;k<3;k++)await pillar();if(!full(bot.blockAt(origin.offset(0,-1,0))))throw Error('ORIGINAL_FLOOR_NOT_RESTORED');activeBurial=null;for(let i=start+1;i<=target;i++){const q=route[i],prev=route[i-1];guard(q);if(!full(bot.blockAt(q.offset(0,-1,0))))throw Error('ROUTE_FLOOR');if(q.y>prev.y)await cut(prev.offset(0,2,0));if(q.y<prev.y)await cut(q.offset(0,2,0));for(const y of[1,0])await cut(q.offset(0,y,0));await go(q);trace.push(q);actual=i;done++;console.log('ACTUAL_TRAIL',i,q.toString());}if(!profile(route[target]))throw Error('END_PROFILE_CHANGED');await bury(route[target]);}
catch(e){issue=e.message;console.log('TRAVEL_ISSUE',issue);retreat=true;try{if(!lost){if(activeBurial&&bot.entity.position.floored().x===activeBurial.x&&bot.entity.position.floored().z===activeBurial.z&&bot.entity.position.y<=activeBurial.y)await bury(activeBurial);else{for(const q of trace.slice().reverse())await go(q);await bury(origin);}}}catch(e){console.log('RECOVERY_FAILED',e.message);}}
finally{bot.clearControlStates();bot.pathfinder.setGoal(null);bot.removeListener('death',life);bot.removeListener('respawn',life);}
return{issue,lost,done,actual,target,hp:bot.health,p:bot.entity.position,sealed:cube(bot.entity.position.floored()),burial:global.p3TravelBurial,inventory:bot.inventory.items().map(i=>[i.name,i.count,i.durabilityUsed]),piglins:Object.values(bot.entities).filter(e=>e.name==='piglin').map(e=>[e.id,e.position,e.heldItem?.name])};